				bpf_net_ctx_clear(bpf_net_ctx);
				goto out_redir;
			}
			break;
		case XDP_TX:
			generic_xdp_tx(*pskb, xdp_prog);
			break;
		}
		bpf_net_ctx_clear(bpf_net_ctx);
		return XDP_DROP;
	}
	bpf_net_ctx_clear(bpf_net_ctx);
}

